// Parse tolérant + mappe vers les COLONNES du Sheet (crm-schema.json).
const form = $('Formulaire — deep-dive').first().json;
const prospect = (form['Prospect (nom exact du CRM)'] || '').toString().trim();
return items.map((it) => {
  const raw = it.json.text || it.json.response || it.json.output || '';
  let x = {};
  try { x = JSON.parse(raw); } catch (e) {
    const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { x = JSON.parse(m[0]); } catch (_) {} }
  }
  const num = (v) => { const n = parseFloat(String(v).replace(',', '.')); return Number.isFinite(n) ? Math.abs(n) : ''; };
  const now = new Date().toISOString().slice(0, 16).replace('T', ' ');
  const auditParts = [x.marketPosition ? 'Position: ' + x.marketPosition : '', x.audience ? 'Parle à: ' + x.audience : '', x.summary || ''].filter(Boolean);
  const out = {
    prospect,
    rating: x.rating !== undefined ? num(x.rating) : '',
    reviews: x.reviews !== undefined ? num(x.reviews) : '',
    website: x.websiteState || '',
    competition: x.localCompetition || '',
    process: x.currentProcess || '',
    missedCalls: x.missedCallsPerWeek !== undefined ? num(x.missedCallsPerWeek) : '',
    avgTicket: x.avgTicket !== undefined ? num(x.avgTicket) : '',
    audit: auditParts.join(' · ').slice(0, 900),
    problems: Array.isArray(x.problems) ? x.problems.join(' | ').slice(0, 600) : '',
    offer: x.personalizedOffer || '',
    history: `[${now}] Deep-dive importé (recherche externe structurée)`
  };
  // ne pas écraser avec du vide : on retire les clés vides (hors prospect)
  for (const k of Object.keys(out)) { if (k !== 'prospect' && out[k] === '') delete out[k]; }
  return { json: out };
});
